# Simulating HDFS block distribution and replication logic

class HDFSCluster:
    def __init__(self, block_size_mb=128, replication=3):
        self.block_size_mb = block_size_mb
        self.replication = replication
        self.namenode_metadata = {}
        self.datanodes = {f"DN_{i}": {} for i in range(1, 6)}

    def upload_file(self, filename, size_mb):
        import math
        num_blocks = math.ceil(size_mb / self.block_size_mb)
        blocks = [f"{filename}_block_{i}" for i in range(num_blocks)]
        self.namenode_metadata[filename] = blocks

        # Simple round-robin block placement with replication
        dn_keys = list(self.datanodes.keys())
        for idx, block in enumerate(blocks):
            for r in range(self.replication):
                target_dn = dn_keys[(idx + r) % len(dn_keys)]
                self.datanodes[target_dn][block] = f"{size_mb}MB"

# Run simulation
cluster = HDFSCluster()
cluster.upload_file("sensor_logs.csv", 400)
print("NameNode Metadata:", cluster.namenode_metadata)
print("DataNode 1 Storage:", cluster.datanodes["DN_1"])

