def check_replication(cluster, filename, min_replicas=2):
    blocks = cluster.namenode_metadata.get(filename, [])
    at_risk_blocks = []
    for block in blocks:
        count = sum(1 for dn in cluster.datanodes.values() if block in dn)
        if count < min_replicas:
            at_risk_blocks.append(block)
    return at_risk_blocks

