    # Input lines formatted as: MATRIX_NAME row col val
    # Example: A 0 0 1
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        mat_name, r, c, val = parts[0], int(parts[1]), int(parts[2]), float(parts[3])

        if mat_name == 'A':
            # Key is k (which is column of A), value tags A with row i and val
            print(f"{c}\tA\t{r}\t{val}")
        elif mat_name == 'B':
